class RuleTable:
    def __init__(self):
        self._exact = {}
        self._namespace = {}

    def add_exact(self, key, action):
        self._exact[key] = action

    def add_namespace(self, prefix, action):
        self._namespace[prefix] = action

    def resolve(self, key):
        if key in self._exact:
            return self._exact[key]
        best = None
        best_len = -1
        for prefix, action in self._namespace.items():
            if key.startswith(prefix) and len(prefix) > best_len:
                best = action
                best_len = len(prefix)
        return best
